// Fail OPEN: if the validator is unreachable we let the sign-up through
// (never block real users because of an outage).
const r = $input.first().json || {};
const email = $('Sign-up webhook').first().json.body?.email || '';
if (!email) {
  return [{ json: { email, allowed: false, reason: 'missing_email' } }];
}
if (!r.success && r.isValidSyntax !== false) {
  return [{ json: { email, allowed: true, reason: 'validation_unavailable' } }];
}
const flags = r.flags || {};
let allowed = r.deliverable === true && !flags.isDisposable;
let reason = r.verdict || 'unknown';
if (!r.isValidSyntax) { allowed = false; reason = 'invalid_syntax'; }
else if (flags.isDisposable) { reason = 'disposable_email'; }
else if (!r.deliverable) { reason = 'domain_cannot_receive_email'; }
return [{ json: {
  email,
  allowed,
  reason,
  quality_score: r.qualityScore ?? null,
  is_business_email: !!flags.isB2BCorporate,
  is_role_account: !!flags.isRoleAccount,
  mail_provider: r.mailServer?.provider ?? null,
} }];
